create table public.assignments (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,course_id uuid not null references public.courses(id) on delete cascade,title text not null check(char_length(trim(title)) between 2 and 200),instructions text,due_at timestamptz,max_score numeric(8,2),is_published boolean not null default false,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()));create index assignments_tenant_course_idx on public.assignments(tenant_id,course_id);alter table public.assignments enable row level security;revoke all on public.assignments from anon,authenticated;create policy assignments_select_tenant on public.assignments for select to authenticated using(tenant_id=public.current_tenant_id());
insert into public.permissions(code,name,description) values('assignments.read','Read assignments','View assignments'),('assignments.create','Create assignments','Create assignments'),('assignments.update','Update assignments','Maintain assignments'),('assignments.delete','Delete assignments','Delete assignments') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER') and p.code like 'assignments.%' on conflict do nothing;
